const D = { energy: .6, scale: 1, density: .6, speed: 1, wind: .5, hue: 96, x: .5, y: .5, style: 'canopy', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Lying on the forest floor looking straight up. Four tiers of canopy hang between you
// and the sky, each at its own depth, each swaying at its own rate — so the gaps between
// leaves open and close in true parallax and the sky comes and goes through them.
// Crown shyness keeps a seam of sky between neighbouring crowns. Trunks converge outward
// to the frame edges, because looking up is a perspective too.
// Wind never settles, so this can never converge to a steady frame. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
function hsh(ix,iy){ let h=(Math.imul(ix,374761393)+Math.imul(iy,668265263)+Math.imul(sd,1442695041))|0;
  h=Math.imul(h^(h>>>13),1274126177)|0; return ((h^(h>>>16))>>>0)/4294967295; }   // >>> : a >> fold caps the hash at 0.5
function fr(i){ return hsh((i*7+13)|0, (i*31+5)|0); }
function vn(x,y){ const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=hsh(ix,iy), b=hsh(ix+1,iy), c=hsh(ix,iy+1), d=hsh(ix+1,iy+1);
  return a+(b-a)*wx+(c-a)*wy+(a-b-c+d)*wx*wy; }
function fbm(x,y){ return .55*vn(x,y)+.28*vn(x*2.03+5.1,y*2.03-3.3)+.17*vn(x*4.07-2.7,y*4.07+7.9); }
function fbm4(x,y){ return .46*vn(x,y)+.26*vn(x*2.03+5.1,y*2.03-3.3)+.17*vn(x*4.07-2.7,y*4.07+7.9)+.11*vn(x*8.11+1.3,y*8.11-4.7); }
function hsv(h,s,v){ h=(((h%360)+360)%360)/60; const c=v*s, xx=c*(1-Math.abs(h%2-1)), m=v-c;
  let r,g2,b2;
  if(h<1){r=c;g2=xx;b2=0}else if(h<2){r=xx;g2=c;b2=0}else if(h<3){r=0;g2=c;b2=xx}
  else if(h<4){r=0;g2=xx;b2=c}else if(h<5){r=xx;g2=0;b2=c}else{r=c;g2=0;b2=xx}
  return [(r+m)*255,(g2+m)*255,(b2+m)*255]; }

const sty = P.style, en = cl(P.energy,0,1), wnd = cl(P.wind,0,1);
const Hh = ((P.hue%360)+360)%360, tt = K.t;
const bp = sty==='blueprint', xr = sty==='xray', aut = sty==='autumn', noc = sty==='nocturne';

// ---- palette. The sky is the LIGHT SOURCE here — so it is deliberately NOT blown white.
// A canopy read is dark leaf mass against a luminous but toned sky; a pale sky filling the
// gaps is exactly how this piece would fail (rice_terraces: lum 0.59, reads washed). ----
let skyC, skyEdge, leafD, leafL, leafT, barkC;
if (bp)       { skyC=[206,54,30];  skyEdge=[212,68,15]; leafD=[196,64,20];  leafL=[186,44,72]; leafT=[190,50,54]; barkC=[200,66,12]; }
else if (xr)  { skyC=[214,42,10];  skyEdge=[220,50,6];  leafD=[188,26,26];  leafL=[176,10,92]; leafT=[182,16,62]; barkC=[196,30,16]; }
else if (aut) { skyC=[34,26,66];   skyEdge=[28,34,44];  leafD=[16,72,32];   leafL=[38,86,84];  leafT=[26,80,60];  barkC=[20,42,14]; }
else if (noc) { skyC=[224,40,52];  skyEdge=[230,54,26]; leafD=[206,42,11];  leafL=[212,22,50]; leafT=[208,32,28]; barkC=[214,38,8]; }
else          { skyC=[Hh+96,26,62]; skyEdge=[Hh+104,38,38]; leafD=[Hh-8,72,16]; leafL=[Hh+8,64,66]; leafT=[Hh+2,70,38]; barkC=[Hh-40,30,11]; }

const sc = cl(P.scale,.5,2.2);
const cx0 = cl(P.x,0,1), cy0 = cl(P.y,0,1);

// ---- perpetual drift: the wind field advects for ever, never returning ----
if (S.wd == null) S.wd = 0;
if (S.lt == null || K.t < S.lt) S.lt = K.t;
const dt = cl(K.t - S.lt, 0, .1); S.lt = K.t;
S.wd += dt * P.speed * (.10 + .34*wnd) * (.80 + .20*Math.sin(tt*.053) + K.swell*.14);
const wd = S.wd;

const BW = 208, BH = Math.max(64, Math.round(BW*height/width));
if (!S.g || S.bk !== BW+'x'+BH){ if(S.g){ try{S.g.remove();}catch(e){} }
  S.g = createGraphics(BW,BH); S.g.pixelDensity(1); S.bk = BW+'x'+BH; }
const g = S.g; g.loadPixels(); const px = g.pixels;

const cSk = hsv(skyC[0], skyC[1]/100, skyC[2]/100);
const cSe = hsv(skyEdge[0], skyEdge[1]/100, skyEdge[2]/100);
const cLd = hsv(leafD[0], leafD[1]/100, leafD[2]/100);
const cLl = hsv(leafL[0], leafL[1]/100, leafL[2]/100);
const cLt = hsv(leafT[0], leafT[1]/100, leafT[2]/100);

// four tiers, far (0, highest crowns, smallest leaves) -> near (3, biggest)
const NT = 4;
const TR = [];
for (let i=0;i<NT;i++){
  const dep = 1 - i/(NT-1);                     // 1 = highest/farthest, 0 = nearest
  // each tier sways on its OWN incommensurate pair of rates: this is the parallax
  const sx = Math.sin(tt*(.23+i*.137)+i*1.7)*.55 + Math.sin(tt*(.61+i*.083)+i*.7)*.30;
  const sy = Math.cos(tt*(.19+i*.111)+i*2.3)*.50 + Math.sin(tt*(.47+i*.071)+i*1.9)*.28;
  const amp = (.010 + Math.pow(1-dep,1.5)*.075)*(.25+wnd*1.6);
  TR.push({
    dep: dep,
    freq: 3.0 + dep*8.5,                        // far crowns = finer leaf grain
    ox: sx*amp + wd*(.05 + (1-dep)*.16),        // + a perpetual one-way advection
    oy: sy*amp*.7,
    ph: i*23.7,
    cover: .40 + (1-dep)*.22                    // near tiers block more sky
  });
}

// the sun's disc, low-ish and wandering — sunflecks track it
const sunX = cx0 + .20*Math.sin(tt*.0211) + .09*Math.sin(tt*.0533+1.4);
const sunY = cy0 - .10 + .13*Math.sin(tt*.0173+2.2) + .06*Math.sin(tt*.0431);
const gustB = .70 + .20*Math.sin(tt*.31) + .10*Math.sin(tt*.73+1.1);

for (let j=0;j<BH;j++){
  const ny = (j+.5)/BH;
  for (let i=0;i<BW;i++){
    const nx = (i+.5)/BW;
    // --- looking UP is a perspective too: everything splays away from the zenith ---
    const zx = (nx-cx0), zy = (ny-cy0)*(height/width);
    const rz = Math.sqrt(zx*zx+zy*zy);
    const splay = 1 + rz*rz*1.9;                 // crowns compress toward the frame edge
    // --- sky: luminous at the zenith, deepening to the edges. Toned, never blown. ---
    const sk = Math.pow(cl(1-rz*1.5,0,1), 1.3);
    let r = cSe[0]+(cSk[0]-cSe[0])*sk, g2 = cSe[1]+(cSk[1]-cSe[1])*sk, b2 = cSe[2]+(cSk[2]-cSe[2])*sk;
    // the sun burning through, only where the canopy lets it
    const dsx = (nx-sunX)*1.5, dsy = (ny-sunY)*1.5*(height/width);
    const dsun = Math.sqrt(dsx*dsx+dsy*dsy);
    const sunGl = Math.exp(-dsun*5.5)*(.35+en*.9);
    r += (255-r)*sunGl*.55; g2 += (255-g2)*sunGl*.55; b2 += (250-b2)*sunGl*.50;

    // --- canopy tiers: front to back, each occluding the sky behind it ---
    let openness = 1;                            // how much sky still gets through
    for (let k=NT-1;k>=0;k--){
      const T = TR[k];
      const fx = (zx*splay)*T.freq + T.ox*T.freq + T.ph;
      const fy = (zy*splay)*T.freq + T.oy*T.freq - T.ph*.6;
      // leaf mass: fbm threshold. Crown shyness — neighbouring crowns keep a seam of sky —
      // comes from a second, coarser cell field cut out of the mass.
      const mass0 = fbm4(fx, fy);
      const crown = fbm(fx*.28 - T.ph*.2, fy*.28 + T.ph*.13);
      const seam = cl(Math.abs(crown-.5)*7.0, 0, 1);        // ~0 along crown boundaries
      const cover = cl((mass0 - (1-T.cover*P.density*1.7))*3.4, 0, 1) * seam;
      if (cover <= .001) continue;
      // leaf shading: backlit leaves GLOW (translucent), leaves in shadow go near-black.
      // That two-sided contrast is the whole read — and it swings as the tiers sway.
      const back = Math.exp(-dsun*2.2)*(.30+en*1.0);
      const grain = fbm4(fx*3.1+11.3, fy*3.1-7.1);
      const trans = cl(back*(.35+grain*.9)*gustB, 0, 1);
      let lr = cLd[0]+(cLt[0]-cLd[0])*cl(grain*1.2,0,1);
      let lg = cLd[1]+(cLt[1]-cLd[1])*cl(grain*1.2,0,1);
      let lb = cLd[2]+(cLt[2]-cLd[2])*cl(grain*1.2,0,1);
      lr += (cLl[0]-lr)*trans; lg += (cLl[1]-lg)*trans; lb += (cLl[2]-lb)*trans;
      // depth: higher tiers are hazier and paler (there is air between them)
      const ha = T.dep*T.dep*.42;
      lr += (cSk[0]*.72-lr)*ha; lg += (cSk[1]*.72-lg)*ha; lb += (cSk[2]*.72-lb)*ha;
      const a2 = cover*openness;
      r += (lr-r)*a2; g2 += (lg-g2)*a2; b2 += (lb-b2)*a2;
      openness *= 1-a2*.94;
    }
    // --- trunks: converging outward toward the frame edges ---
    const ang = Math.atan2(zy, zx);
    const tk = fbm(ang*2.1+7.3, rz*.6 + wd*.02);
    const trunk = cl((tk-.62)*5.0,0,1) * cl((rz-.30)*2.6,0,1);
    if (trunk > .002){
      const bc = hsv(barkC[0], barkC[1]/100, barkC[2]/100);
      const bg = fbm(ang*30+3.1, rz*22);
      const sh = .55+bg*.75;
      r += (bc[0]*sh-r)*trunk*.92; g2 += (bc[1]*sh-g2)*trunk*.92; b2 += (bc[2]*sh-b2)*trunk*.92;
    }
    const o = 4*(j*BW+i);
    px[o]=cl(r,0,255); px[o+1]=cl(g2,0,255); px[o+2]=cl(b2,0,255); px[o+3]=255;
  }
}
g.updatePixels();
push();
if (P.alpha<100) tint(0,0,100,P.alpha);
image(g,0,0,width,height);
pop();

const AL = P.alpha/100;
const dens = cl(P.density,0,1);

// ---- near leaves: a few crisp, big, out-at-the-lens leaves, swinging on their petioles.
// They give scale and a true nearest plane. ----
push();
noStroke();
const NL = Math.round(6 + dens*22);
for (let i=0;i<NL;i++){
  const f1 = fr(i*4+11), f2 = fr(i*4+12), f3 = fr(i*4+13), f4 = fr(i*4+14);
  // anchored off-frame at the edges, hanging in
  const edge = Math.floor(f1*4);
  let ax, ay;
  if (edge===0){ ax = f2*width; ay = -height*.04; }
  else if (edge===1){ ax = f2*width; ay = height*1.04; }
  else if (edge===2){ ax = -width*.04; ay = f2*height; }
  else { ax = width*1.04; ay = f2*height; }
  const sw = Math.sin(tt*(.7+f3*1.5)+f1*6.28)*(.10+wnd*.40) + Math.sin(tt*(1.9+f4*2.1)+f2*6.28)*(.05+wnd*.16);
  const len = u*(.10+f3*.22)*sc;
  const dirx = (cx0*width-ax), diry = (cy0*height-ay);
  const dl = Math.hypot(dirx,diry)+1e-3;
  const th = Math.atan2(diry,dirx) + sw;
  const tx = ax + Math.cos(th)*len, ty = ay + Math.sin(th)*len;
  const trans = cl(Math.exp(-Math.hypot(tx/width-sunX, (ty/height-sunY))*3.0)*(.4+en*1.0),0,1);
  const cc = [ leafD[0]+(leafL[0]-leafD[0])*trans, leafD[1]+(leafL[1]-leafD[1])*trans,
               leafD[2]+(leafL[2]-leafD[2])*trans ];
  push();
  translate(tx, ty); rotate(th + Math.PI*.5 + sw*.4);
  fill(cc[0], cc[1], cc[2]*(.6+f4*.5), (78+trans*20)*AL);
  const lw2 = len*(.26+f4*.18);
  beginShape();
  vertex(0, -len*.42);
  bezierVertex(lw2, -len*.16, lw2*.9, len*.22, 0, len*.44);
  bezierVertex(-lw2*.9, len*.22, -lw2, -len*.16, 0, -len*.42);
  endShape(CLOSE);
  // midrib
  stroke(cc[0], cc[1]*.7, cc[2]*1.5+8, 40*AL); strokeWeight(Math.max(.5,u*.0012));
  line(0,-len*.40,0,len*.42);
  noStroke();
  pop();
}
pop();

// ---- sunflecks: soft pools of light punched through the canopy, drifting with the tiers ----
push();
blendMode(ADD);
noStroke();
const NF = Math.round(4 + dens*14);
for (let i=0;i<NF;i++){
  const f1 = fr(i*6+201), f2 = fr(i*6+202), f3 = fr(i*6+203);
  const fx = sunX*width + Math.sin(tt*(.13+f1*.29)+f1*6.28)*width*(.06+f2*.20)
                        + Math.sin(tt*(.37+f3*.2)+f2*6.28)*width*.03;
  const fy = sunY*height + Math.cos(tt*(.11+f2*.24)+f3*6.28)*height*(.06+f1*.18);
  const fs = u*(.012+f3*.055)*(.5+en*1.1)*sc;
  const br = (.30+en*.75)*(.55+.45*Math.sin(tt*(.9+f1*1.6)+f2*6.28))*gustB;
  for (let k=3;k>=1;k--){
    fill(skyC[0]-14, skyC[1]*.28, 100, (bp?5:9)*br/k*AL);
    ellipse(fx, fy, fs*k*1.6, fs*k*1.5);
  }
}
blendMode(BLEND);
pop();

// ---- pollen / dust drifting up through the shafts ----
push();
blendMode(ADD);
noStroke();
const NP = Math.round(10 + dens*70);
for (let i=0;i<NP;i++){
  const f1 = fr(i*3+301), f2 = fr(i*3+302), f3 = fr(i*3+303);
  const py = ((f2 - tt*(.004+f3*.017)*P.speed) % 1.1 + 1.1) % 1.1 - .05;
  const pxx = f1 + Math.sin(tt*(.3+f3*.7)+f1*6.28)*.030 + Math.sin(tt*(.09+f2*.2))*.045;
  const d2 = Math.hypot(pxx-sunX, (py-sunY));
  const br = (.10 + Math.exp(-d2*3.4)*1.1)*(.4+en*.8);
  fill(skyC[0]-20, 12, 100, 34*br*AL);
  ellipse(pxx*width, py*height, u*(.0016+f3*.0042)*(1+br), u*(.0016+f3*.0042)*(1+br));
}
blendMode(BLEND);
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
drawingContext.globalAlpha = 1;
